def _is_system_agent_id(agent_id: Optional[str]) -> bool:
    if not agent_id:
        return False
    aid = str(agent_id).strip().lower()
    if "::" in aid:
        aid = aid.split("::")[-1]
    # Explicit system agent IDs
    if aid in {GIT_MANAGER_AGENT_ID.lower(), MASTER_AGENT_ID.lower(), DEPLOY_AGENT_ID.lower()}:
        return True
    # Pattern-based: M_agent_XX or G_agent_XX are always system agents
    if aid.startswith("m_agent_") or aid.startswith("g_agent_"):
        return True
    return False


def _extract_dev_agent_sequence(agent_id: Optional[str]) -> Optional[int]:
    source = str(agent_id or "").strip().lower()
    if not source or _is_system_agent_id(source):
        return None
    match = _re.search(r"(?:agent|shared)_(\d+)", source)
    if not match:
        match = _re.search(r"(\d+)", source)
        if not match:
            return None
    return int(match.group(1))


def get_default_agent_name(agent_id: Optional[str]) -> str:
    if agent_id == GIT_MANAGER_AGENT_ID:
        return "Git Manager"
    if agent_id == MASTER_AGENT_ID:
        return "Master Agent"
    sequence = _extract_dev_agent_sequence(agent_id)
    if sequence is None:
        return "Agent"
    return f"Agent {sequence}"


def normalize_agent_name(agent_id: Optional[str], name: Optional[str]) -> str:
    default_name = get_default_agent_name(agent_id)
    cleaned = str(name or "").strip()
    if not cleaned:
        return default_name
    if _is_system_agent_id(agent_id):
        return default_name

    normalized = cleaned.lower()
    raw_id = str(agent_id or "").strip().lower()
    if normalized in {
        "requirements validator",
        "risk assessment",
        "resource estimation",
    }:
        return default_name
    if normalized == raw_id or normalized == raw_id.replace("_", " "):
        return default_name
    if _re.fullmatch(r"(shared|dedicated|dev)[ _-]*agent(?:[ _-]*\d+)?", normalized):
        return default_name
    if _re.fullmatch(r"agent(?:[ _-]*\d+)?", normalized):
        return default_name
    return cleaned


def _next_dev_agent_sequence(project_agents: Dict[str, Dict[str, Any]]) -> int:
    used_numbers = {
        sequence
        for sequence in (_extract_dev_agent_sequence(agent_id) for agent_id in project_agents)
        if sequence is not None
    }
    next_number = 1
    while next_number in used_numbers:
        next_number += 1
    return next_number


def build_external_agent_username(agent_id: Optional[str], fallback_name: Optional[str] = None) -> str:
    raw_id = str(agent_id or "").strip()
    source_id = raw_id.lower()
    
    # System agents keep their own ID format (preserve format for external stg-nxdune username)
    if source_id.startswith("m_agent_") or source_id.startswith("g_agent_") or "::" in source_id:
        return raw_id

    # 1. Query the database to resolve sequential "agentX" based on project agents list
    try:
        from database import SessionLocal
        import models as db_models
        db = SessionLocal()
        try:
            agent_rec = db.query(db_models.Agent).filter(db_models.Agent.id == raw_id).first()
            if agent_rec and agent_rec.project_token:
                project_token = agent_rec.project_token
                # Get all agents for this project, ordered by created_at and id
                project_agents = db.query(db_models.Agent).filter(
                    db_models.Agent.project_token == project_token
                ).order_by(db_models.Agent.created_at.asc(), db_models.Agent.id.asc()).all()
                
                # Filter out system agents
                dev_agents = [
                    a for a in project_agents 
                    if not (a.id.lower().startswith("m_agent_") or a.id.lower().startswith("g_agent_") or "::" in a.id)
                ]
                
                # Find the index of agent_id in dev_agents
                for idx, a in enumerate(dev_agents):
                    if a.id == raw_id:
                        return f"agent{idx + 1}"
        finally:
            db.close()
    except Exception as e:
        logger.warning(f"Failed to resolve external agent username from DB: {e}")
        
    # Check for instance suffix with "#" (e.g. agent_01#2)
    if "#" in source_id:
        parts = source_id.split("#")
        instance_num = int(parts[1])
        # Direct mapping: instance 1 -> agent1, instance 2 -> agent2, etc.
        return f"agent{instance_num}"
        
    # Check for flat clone suffix with "_" (e.g. agent_01_2)
    match = _re.search(r"(?:agent|shared)_(\d+)(?:_(\d+))?", source_id)
    if match:
        base_seq = int(match.group(1))
        clone_seq = int(match.group(2)) if match.group(2) else 1
        
        # Flat sequential calculation for clones: base + (clone - 1) * 2
        sequence = base_seq + (clone_seq - 1) * 2
        
        # Shared agents use agent3, agent4, etc. to avoid conflicts with dedicated agents
        if source_id.startswith("shared_"):
            sequence = sequence + 2
            
        return f"agent{sequence}"

    # Fallback to simple trailing digits search
    match = _re.search(r"(\d+)$", source_id)
    if match:
        sequence = int(match.group(1))
        if source_id.startswith("shared_"):
            sequence = sequence + 2
        return f"agent{sequence}"

    fallback = normalize_agent_name(agent_id, fallback_name)
    fallback_match = _re.search(r"(\d+)$", fallback.lower())
    if fallback_match:
        sequence = int(fallback_match.group(1))
        if "shared" in fallback.lower():
            sequence = sequence + 2
        return f"agent{sequence}"

    normalized = _re.sub(r"[^a-z0-9]", "", fallback.strip().lower())
    return normalized or "agent"

_project_states: Dict[str, Dict[str, Any]] = {}

# Simple module-level bootstrap completion flag.
# Bootstrap agent sets this to True when it successfully pushes.
# All other agents check this before picking tasks.
# Keyed by project_token so multiple projects work independently.
# _bootstrap_pushed replaced with persistent bootstrap_persistence module


def _new_repo_bootstrap_state() -> Dict[str, Any]:
    return {
        "repo_url": None,
        "required": None,
        "agent_id": None,
        "status": "unknown",
        "source_branch": None,
        "message": "",
        "started_at": None,
        "completed_at": None,
    }

def _project_key(project_token: Optional[str]) -> str:
    token = (project_token or "").strip()
    return token or DEFAULT_PROJECT_TOKEN

def _make_asyncio_lock() -> asyncio.Lock:
    """Create an asyncio.Lock safely, always bound to the running event loop."""
    try:
        asyncio.get_running_loop()
    except RuntimeError:
        # No running loop — create a new one temporarily so the Lock is valid
        # when the event loop starts. In practice this path should not be hit
        # during normal async execution.
        pass
    return asyncio.Lock()


def _make_asyncio_event() -> asyncio.Event:
    """Create an asyncio.Event safely."""
    try:
        asyncio.get_running_loop()
    except RuntimeError:
        pass
    return asyncio.Event()


def _ensure_project_state(project_token: Optional[str]) -> Dict[str, Any]:
    key = _project_key(project_token)
    state = _project_states.get(key)
    if state is None:
        state = {
            "agent_states": {},
            "claimed_task_ids": set(),
            "task_ledger": {},
            "event_bus": AgentEventBus(),
            "task_claim_lock": _make_asyncio_lock(),
            "task_progress_state": {},
            "timer_log_state": {},
            "completed_tasks": [],
            "tasks": [],
            "master_task_context": [],
            "brd_analysis": {},
            "master_note_cache": {},
            "master_note_lock": _make_asyncio_lock(),
            "task_token": None,
            "git_merge_queue": [],
            "git_merge_running": False,
            "git_merge_lock": _make_asyncio_lock(),
            "git_merge_inflight": set(),
            "merged_branches": [],
            "task_dag": {},
            "repo_bootstrap": _new_repo_bootstrap_state(),
            "repo_bootstrap_lock": _make_asyncio_lock(),
            "repo_bootstrap_event": _make_asyncio_event(),
            "completed_milestones_synced": set(),
            "completed_sprints_synced": set(),
            "project_status_synced": None,
            "status_sync_lock": _make_asyncio_lock(),
            "note_title_cache": {},
            "note_payload_cache": {},
            "persisted_assignment_restore": {},
            "workspace_contract_probe": {},
        }
        _project_states[key] = state
    else:
        state.setdefault("completed_milestones_synced", set())
        state.setdefault("completed_sprints_synced", set())
        state.setdefault("project_status_synced", None)
        if "status_sync_lock" not in state:
            state["status_sync_lock"] = _make_asyncio_lock()
        state.setdefault("note_title_cache", {})
        state.setdefault("note_payload_cache", {})
        state.setdefault("persisted_assignment_restore", {})
        state.setdefault("workspace_contract_probe", {})
        state.setdefault("tasks", [])
        state.setdefault("master_task_context", [])
        state.setdefault("brd_analysis", {})
        state.setdefault("master_note_cache", {})
        if "master_note_lock" not in state:
            state["master_note_lock"] = _make_asyncio_lock()
        if "task_claim_lock" not in state:
            state["task_claim_lock"] = _make_asyncio_lock()
        state.setdefault("task_ledger", {})
        state.setdefault("task_dag", {})
        if "event_bus" not in state:
            state["event_bus"] = AgentEventBus()
    return state

def _get_agent_states(project_token: Optional[str]) -> Dict[str, Dict[str, Any]]:
    return _ensure_project_state(project_token)["agent_states"]


def get_project_agent_creation_lock(project_token: Optional[str]) -> asyncio.Lock:
    """Get the agent creation lock for a project to serialize add_agent calls."""
    key = _project_key(project_token)
    if key not in _agent_creation_locks:
        _agent_creation_locks[key] = _make_asyncio_lock()
    return _agent_creation_locks[key]


def _flatten_seed_checklists(raw_groups: Any) -> List[Dict[str, Any]]:
    flattened: List[Dict[str, Any]] = []
    if not isinstance(raw_groups, list):
        return flattened

    for group in raw_groups:
        if not isinstance(group, dict):
            continue
        items = group.get("items")
        if not isinstance(items, list):
            continue
        for item in items:
            if isinstance(item, dict):
                text = str(item.get("text") or item.get("title") or "").strip()
                completed = bool(item.get("completed"))
            else:
                text = str(item or "").strip()
                completed = False
            if text:
                flattened.append({"text": text, "completed": completed})
    return flattened


def _extract_task_checklist_items(task: Dict[str, Any], limit: Optional[int] = None) -> List[str]:
    collected: List[str] = []

    def extend(raw_value: Any) -> None:
        if isinstance(raw_value, dict):
            if isinstance(raw_value.get("items"), list):
                extend(raw_value.get("items"))
                return
            if isinstance(raw_value.get("checklistItems"), list):
                extend(raw_value.get("checklistItems"))
                return
            text = str(
                raw_value.get("text")
                or raw_value.get("title")
                or raw_value.get("name")
                or ""
            ).strip()
            if text:
                collected.append(text)
            return
        if isinstance(raw_value, list):
            for item in raw_value:
                extend(item)
            return
        text = str(raw_value or "").strip()
        if text:
            collected.append(text)

    extend(task.get("checklist"))
    extend(_flatten_seed_checklists(task.get("checklists")))

    task_json = task.get("task_json") if isinstance(task.get("task_json"), dict) else {}
    if task_json:
        extend(task_json.get("checklist"))
        extend(_flatten_seed_checklists(task_json.get("checklists")))

    normalized: List[str] = []
    seen = set()
    for item in collected:
        text = " ".join(str(item or "").split())
        if not text or text in seen:
            continue
        seen.add(text)
        normalized.append(text)
        if isinstance(limit, int) and limit > 0 and len(normalized) >= limit:
            break
    return normalized


def _build_brd_analysis_context(brd_analysis: Any, max_chars: int = 0) -> str:
    if isinstance(brd_analysis, str):
        if max_chars > 0:
            return str(brd_analysis).strip()[:max_chars]
        return str(brd_analysis).strip()
    if not isinstance(brd_analysis, dict):
        return ""

    def to_text(value: Any, limit: int) -> str:
        if value in (None, "", [], {}):
            return ""
        if isinstance(value, str):
            text = value.strip()
        else:
            try:
                text = json.dumps(value, ensure_ascii=True, indent=2)
            except Exception:
                text = str(value).strip()
        if limit != float('inf') and len(text) > limit:
            return text[: max(0, int(limit) - 3)].rstrip() + "..."
        return text

    sections: List[str] = []
    seen_values = set()
    preferred_keys = [
        ("summary", "Summary"),
        ("analysis", "Detailed Analysis"),
        ("projectMeta", "Project Metadata"),
        ("businessGoals", "Business Goals"),
        ("functionalRequirements", "Functional Requirements"),
        ("nonFunctionalRequirements", "Non-Functional Requirements"),
        ("technicalRecommendations", "Technical Recommendations"),
        ("risks", "Risks"),
        ("assumptions", "Assumptions"),
        ("governanceContext", "Governance Context"),
    ]

    per_section_limit = max(240, max_chars // max(2, len(preferred_keys))) if max_chars > 0 else float('inf')
    for key, label in preferred_keys:
        text = to_text(brd_analysis.get(key), per_section_limit)
        if not text or text in seen_values:
            continue
        sections.append(f"{label}:\n{text}")
        seen_values.add(text)

    if not sections:
        fallback_text = to_text(brd_analysis, float('inf') if max_chars == 0 else max_chars)
        return fallback_text if max_chars == 0 else fallback_text[:max_chars]

    combined = "\n\n".join(sections)
    if max_chars > 0 and len(combined) > max_chars:
        combined = combined[: max(0, max_chars - 3)].rstrip() + "..."
    return combined


async def _post_agent_design_context(
    project_token: Optional[str],
    agent_id: str,
    task: Dict[str, Any],
    branch: str = "",
) -> None:
    """
    Post a structured design contract to the Enhanced Context Service after
    task completion. This allows other agents to see API endpoints, DB tables,
    files created, and other design artifacts produced by this agent.

    The Enhanced Context Service maintains a rich shared state with:
    - api_registry: [{method, path, handler, agent}]
    - database_schema: {tables: {name: {agent, columns}}}
    - file_ownership: {file_path: agent_id}
    - agent_contexts: per-agent context with completed_tasks, created_files, etc.

    Other agents query this via _build_peer_context_block() before they start
    working, so they can build consistent code that integrates properly.
    """
    if not project_token:
        return

    from enhanced_context_service import enhanced_context_service, AgentContextUpdate

    # Gather what this task built — files from ledger, hints from description
    task_id = str(_normalize_task_id(task) or task.get("external_id") or task.get("id") or "")
    task_title = task.get("title") or task.get("taskName") or ""
    task_desc = task.get("description") or ""

    # Read files_written from task ledger
    files_written: List[str] = []
    try:
        state = _ensure_project_state(project_token)
        ledger: dict = state.get("task_ledger", {})
        entry = ledger.get(task_id)
        if entry and entry.files_written:
            files_written = list(entry.files_written)
    except Exception:
        pass

    # Infer API endpoints & DB tables from task title + description keywords
    combined_lower = (task_title + " " + task_desc).lower()
    api_endpoints = []
    if any(w in combined_lower for w in ("login", "register", "auth", "authenticate")):
        api_endpoints.append({"method": "POST", "path": "/auth/login", "handler": "login"})
        api_endpoints.append({"method": "POST", "path": "/auth/register", "handler": "register"})
    if any(w in combined_lower for w in ("project", "projects", "kanban", "board")):
        api_endpoints.append({"method": "GET", "path": "/projects", "handler": "list_projects"})
        api_endpoints.append({"method": "POST", "path": "/projects", "handler": "create_project"})
    if any(w in combined_lower for w in ("task", "tasks", "issue")):
        api_endpoints.append({"method": "GET", "path": "/tasks", "handler": "list_tasks"})
        api_endpoints.append({"method": "POST", "path": "/tasks", "handler": "create_task"})
    if any(w in combined_lower for w in ("comment", "comments", "note")):
        api_endpoints.append({"method": "GET", "path": "/comments", "handler": "list_comments"})
        api_endpoints.append({"method": "POST", "path": "/comments", "handler": "create_comment"})
    if any(w in combined_lower for w in ("user", "profile", "settings")):
        api_endpoints.append({"method": "GET", "path": "/users/me", "handler": "get_profile"})
        api_endpoints.append({"method": "PUT", "path": "/users/me", "handler": "update_profile"})

    # Infer DB tables
    db_tables = []
    if "user" in combined_lower:
        db_tables.append("users")
    if "project" in combined_lower:
        db_tables.append("projects")
    if "task" in combined_lower:
        db_tables.append("tasks")
    if "comment" in combined_lower:
        db_tables.append("comments")

    # Infer shared utilities / integration points
    shared_utils = []
    if "auth" in combined_lower or "jwt" in combined_lower:
        shared_utils.append("auth_middleware")
    if "database" in combined_lower or "db" in combined_lower or "sql" in combined_lower:
        shared_utils.append("database_config")

    # Build and post the context update
    from datetime import datetime
    context_update = AgentContextUpdate(
        agent_id=agent_id,
        timestamp=datetime.utcnow().isoformat(),
        current_task=task_title,
        status="completed",
        completed_tasks=[task_title],
        created_files=files_written,
        api_endpoints=api_endpoints,
        database_tables=db_tables,
        shared_utilities=shared_utils,
        tags=["automated_context", "completion"] + [p.split("/")[-1].split(".")[0] for p in files_written[:5]],
    )

    await enhanced_context_service.update_agent_context(project_token, context_update)
    logger.info(f"[{agent_id}] Design context posted to enhanced context: {len(api_endpoints)} API(s), {len(db_tables)} table(s), {len(files_written)} file(s)")


async def _build_peer_context_block(
    agent_id: str,
    task: Dict[str, Any],
    project_token: Optional[str],
    container_name: Optional[str] = None,
) -> str:
    """
    Build a rich summary of what other agents have already completed.
    When container_name is provided, reads actual file content from the
    container to extract exported symbols, class names, and function
    signatures — so the current agent can import rather than re-implement.

    Also injects the current git repository state (recent commits + file tree)
    so the agent knows exactly what has been built before generating new code.

    Returns a plain-text block like:
        COMPLETED WORK BY OTHER AGENTS (do not re-implement):
          [agent_01] Task 'TASK-01 User Auth' → branch: agent/task-01-user-auth
                     files: app/auth/models.py, app/auth/routes.py
                     Signatures in app/auth/models.py:
                       class User(db.Model):
                       def check_password(self, password: str) -> bool:
    """
    state = _ensure_project_state(project_token)
    ledger: Dict[str, TaskLedgerEntry] = state.get("task_ledger", {})

    # ── Inject current repository state from container ────────────────────────
    repo_state_lines: list = []
    if container_name:
        try:
            # Recent git commits (what's already in the repo)
            git_log = subprocess.run(
                ["docker", "exec", "-w", "/workspace", container_name,
                 "git", "log", "--oneline", "-10"],
                capture_output=True, text=True, timeout=10,
            )
            if git_log.returncode == 0 and git_log.stdout.strip():
                repo_state_lines.append("\n📜 CURRENT REPOSITORY — RECENT COMMITS (do NOT re-implement these):")
                for line in git_log.stdout.strip().splitlines():
                    repo_state_lines.append(f"  {line}")

            # Current file tree (what files already exist)
            git_ls = subprocess.run(
                ["docker", "exec", "-w", "/workspace", container_name,
                 "git", "ls-files"],
                capture_output=True, text=True, timeout=10,
            )
            if git_ls.returncode == 0 and git_ls.stdout.strip():
                existing_files = [f.strip() for f in git_ls.stdout.strip().splitlines() if f.strip()]
                # Cap at 100 files to avoid prompt bloat
                display_files = existing_files[:100]
                repo_state_lines.append(f"\n📁 EXISTING FILES IN REPOSITORY ({len(existing_files)} total):")
                for f in display_files:
                    repo_state_lines.append(f"  {f}")
                if len(existing_files) > 100:
                    repo_state_lines.append(f"  ... and {len(existing_files) - 100} more files")
                repo_state_lines.append(
                    "\n⚠️ CRITICAL: These files ALREADY EXIST. Do not recreate them from scratch. "
                    "If your task requires modifying them, read their current content first and PATCH "
                    "only the required changes."
                )

        except Exception as _repo_err:
            logger.debug(f"[{agent_id}] Repo state inspection failed (non-fatal): {_repo_err}")
    # ─────────────────────────────────────────────────────────────────────────

    completed_by_peers = [
        entry for entry in ledger.values()
        if entry.status == "done" and entry.agent_id != agent_id
    ]

    if not completed_by_peers and not repo_state_lines:
        return ""

    # Keywords that indicate a public interface line worth extracting
    _SIG_PREFIXES = (
        "def ", "async def ", "class ", "export ", "export default",
        "module.exports", "function ", "const ", "interface ", "type ",
        "@app.route", "@router.", "app.get(", "app.post(", "app.put(",
        "app.delete(", "app.patch(", "@api_view", "urlpatterns",
    )

    lines = [
        "=" * 60,
        "COMPLETED WORK BY OTHER AGENTS — DO NOT RE-IMPLEMENT",
        "=" * 60,
    ]

    # Include repo state at the top
    if repo_state_lines:
        lines.extend(repo_state_lines)
        lines.append("")

    # Inject files created/modified by this workstream domain (for cross-restart continuity)
    try:
        import context_manager as ctx_mgr
        live_mem = ctx_mgr.get_live_memory(project_token or "")
        domain = _classify_task_assignment_lane(task)
        if live_mem and domain:
            workstream_files = live_mem.get_workstream_files(domain)
            if workstream_files:
                lines.append(f"\n🛠️ FILES CREATED/MODIFIED BY YOUR WORKSTREAM ({domain}):")
                for wf in workstream_files[:40]:
                    lines.append(f"  - {wf}")
                if len(workstream_files) > 40:
                    lines.append(f"  ... and {len(workstream_files) - 40} more files")
                lines.append("")
    except Exception as _ws_err:
        logger.debug(f"Failed to inject workstream files into context block: {_ws_err}")

    # ── DESIGN CONTRACTS FROM ENHANCED CONTEXT SERVICE ──────────────────────
    # Query the shared context for API endpoints, DB tables, and utilities
    # that other agents have already built. This helps the current agent build
    # consistent code that integrates properly (no naming conflicts, no
    # re-implementing existing endpoints).
    try:
        from enhanced_context_service import enhanced_context_service as _ecs
        if project_token and hasattr(_ecs, 'query_context'):
            api_result = await _ecs.query_context(project_token, "api_endpoints")
            endpoints = api_result.get("endpoints", [])
            # Filter to only OTHER agents' endpoints (not this agent's)
            other_endpoints = [e for e in endpoints if e.get("agent") != agent_id]
            if other_endpoints:
                lines.append("\n🔌 API ENDPOINTS ALREADY REGISTERED BY OTHER AGENTS:")
                for ep in other_endpoints[-12:]:
                    lines.append(f"  {ep.get('method','?')} {ep.get('path','?')} → {ep.get('handler','?')} (by {ep.get('agent','?')})")
                lines.append("")

            db_result = await _ecs.query_context(project_token, "database_schema")
            tables = db_result.get("tables", {})
            if tables:
                lines.append("\n🗄️ DATABASE TABLES ALREADY CREATED BY OTHER AGENTS:")
                for tname in sorted(tables.keys())[:10]:
                    meta = tables[tname]
                    lines.append(f"  - {tname} (by {meta.get('agent','?')})")
                lines.append("")

            util_result = await _ecs.query_context(project_token, "shared_utilities")
            utils = util_result.get("utilities", {})
            other_utils = {k: v for k, v in utils.items() if v != agent_id}
            if other_utils:
                lines.append("\n🧰 SHARED UTILITIES PROVIDED BY OTHER AGENTS:")
                for util_name, owner in sorted(other_utils.items())[:8]:
                    lines.append(f"  - {util_name} (by {owner})")
                lines.append("")
    except Exception as _ctx_err:
        logger.debug(f"[{agent_id}] Enhanced context query failed (non-fatal): {_ctx_err}")
    # ─────────────────────────────────────────────────────────────────────────

    for entry in completed_by_peers[-8:]:
        lines.append(f"\n[{entry.agent_id}] Task: '{entry.task_title}'")
        lines.append(f"  Branch : {entry.branch_name}")
        file_list = ", ".join(entry.files_written[:10])
        if len(entry.files_written) > 10:
            file_list += f" (+{len(entry.files_written) - 10} more)"
        lines.append(f"  Files  : {file_list or 'none recorded'}")

        # Read actual file content from the container to extract signatures
        if container_name and entry.files_written:
            for fpath in entry.files_written[:5]:
                try:
                    cat = subprocess.run(
                        ["docker", "exec", container_name,
                         "cat", f"/workspace/{fpath}"],
                        capture_output=True, text=True, timeout=8,
                    )
                    if cat.returncode != 0 or not cat.stdout.strip():
                        continue
                    sig_lines = []
                    for line in cat.stdout.splitlines():
                        stripped = line.strip()
                        if stripped and any(stripped.startswith(kw) for kw in _SIG_PREFIXES):
                            sig_lines.append(f"    {line.rstrip()}")
                        if len(sig_lines) >= 20:
                            break
                    if sig_lines:
                        lines.append(f"\n  Signatures in {fpath}:")
                        lines.extend(sig_lines)
                except Exception:
                    pass

    if completed_by_peers:
        lines += [
            "\n" + "=" * 60,
            "RULES:",
            "- IMPORT from these files — do not rewrite them.",
            "- Use the EXACT function/class names shown above.",
            "- Reference the correct import path when using these symbols.",
            "- DO NOT create a second implementation of anything listed here.",
            "=" * 60,
        ]

    return "\n".join(lines)

def _normalize_seed_task(task: Dict[str, Any], sequence_number: int, project_token: Optional[str] = None) -> Dict[str, Any]:
    task_id = str(task.get("task_id") or task.get("id") or f"TASK-{sequence_number:02d}").strip()
    title = str(task.get("title") or task.get("taskName") or "Untitled Task").strip()
    task_type = str(task.get("task_type") or task.get("type") or "TASK").strip().upper() or "TASK"
    planned_start = task.get("planned_start") or task.get("startdate") or task.get("start_date")
    planned_end = task.get("planned_end") or task.get("deadline") or task.get("end_date")

    return {
        **dict(task),
        "id": task_id,
        "external_id": task_id,
        "task_id": task_id,
        "taskName": title,
        "title": title,
        "description": str(task.get("description") or "").strip(),
        "task_type": task_type,
        "type": str(task.get("type") or task_type).strip().lower(),
        "status": str(task.get("status") or "todo").strip().lower() or "todo",
        "priority": str(task.get("priority") or "medium").strip().lower() or "medium",
        "wallet": task.get("wallet", task.get("story_points", 0)) or task.get("story_points", 0),
        "story_points": task.get("story_points", task.get("wallet", 0)) or task.get("wallet", 0),
        "sequence_number": task.get("sequence_number", sequence_number),
        "dependencies": [
            str(dep).strip()
            for dep in (task.get("dependencies") or [])
            if str(dep).strip()
        ],
        "linked_tasks": [
            str(dep).strip()
            for dep in (task.get("linked_tasks") or [])
            if str(dep).strip()
        ],
        "checklist": _flatten_seed_checklists(task.get("checklists")),
        "startdate": planned_start,
        "deadline": planned_end,
        "sprint_id": task.get("sprint_id"),
        "sprint_name": task.get("sprint_name"),
        "milestone_id": task.get("milestone_id"),
        "milestone_name": task.get("milestone_name"),
        "_project_token": project_token,
    }


def seed_project_tasks(project_token: Optional[str], tasks: List[Dict[str, Any]]) -> List[Dict[str, Any]]:
    state = _ensure_project_state(project_token)
    normalized_tasks = [
        _normalize_seed_task(task, index + 1, project_token=project_token)
        for index, task in enumerate(tasks or [])
        if isinstance(task, dict)
    ]
    state["master_task_context"] = normalized_tasks
    state["master_note_cache"] = {}
    # NEW: build dependency graph from the seeded tasks
    state["task_dag"] = _build_task_dag(normalized_tasks)
    logger.info(f"[DAG] Built task DAG with {len(state['task_dag'])} nodes")
    return normalized_tasks


def _is_waiting_for_master_plan(agent: Optional[Dict[str, Any]]) -> bool:
    if not isinstance(agent, dict):
        return False
    return str(agent.get("progress_message") or "").strip() == RUN_ALL_WAITING_MESSAGE


def mark_run_all_waiting_state(
    project_token: Optional[str],
    agent_ids: List[str],
) -> None:
    project_agents = _get_agent_states(project_token)
    for agent_id in agent_ids:
        if _is_system_agent_id(agent_id):
            continue
        agent = project_agents.get(agent_id)
        if not agent:
            continue
        agent["status"] = "running"
        agent["progress"] = 0
        agent["progress_message"] = RUN_ALL_WAITING_MESSAGE

    master_agent = project_agents.get(MASTER_AGENT_ID)
    if master_agent:
        master_agent["status"] = "running"
        master_agent["progress"] = 0
        master_agent["progress_message"] = MASTER_BUILDING_MESSAGE

    # ── Start Master Orchestrator ──
    asyncio.create_task(
        _master_orchestrator_loop(project_token),
        name=f"master_orch_{project_token or 'default'}"
    )


def complete_run_all_waiting_state(
    project_token: Optional[str],
    *,
    success: bool,
    error_message: Optional[str] = None,
) -> None:
    project_agents = _get_agent_states(project_token)
    for agent_id, agent in project_agents.items():
        if _is_system_agent_id(agent_id):
            continue
        if not _is_waiting_for_master_plan(agent):
            continue
        if not success:
            agent["status"] = "idle"
            agent["progress"] = 0
            agent["progress_message"] = ""
            if error_message:
                agent["error"] = error_message

    master_agent = project_agents.get(MASTER_AGENT_ID)
    if master_agent:
        master_agent["status"] = "idle"
        master_agent["progress"] = 100 if success else 0
        master_agent["progress_message"] = MASTER_READY_MESSAGE if success else MASTER_FAILED_MESSAGE

def set_project_task_token(project_token: Optional[str], task_token: Optional[str]) -> None:
    if not task_token:
        return
    _ensure_project_state(project_token)["task_token"] = task_token

def get_project_task_token(project_token: Optional[str]) -> Optional[str]:
    return _ensure_project_state(project_token).get("task_token")


def clear_project_runtime_state(project_token: Optional[str]) -> None:
    """Clear in-memory runtime state for a single project token."""
    key = _project_key(project_token)
    _project_states.pop(key, None)
    _preview_states.pop(key, None)

    token = (project_token or "").strip()
    if token:
        _project_tech_specs.pop(token, None)


def clear_all_runtime_state() -> None:
    """Clear all in-memory runtime state after structural agent changes."""
    _project_states.clear()
    _preview_states.clear()
    _project_tech_specs.clear()

def _make_agent(agent_id: str, idx: int = 0) -> Dict[str, Any]:
    """Create a fresh agent state dict."""
    sequence = _extract_dev_agent_sequence(agent_id)
    type_index = (sequence - 1) if sequence is not None else idx
    atype = _AGENT_TYPES[type_index % len(_AGENT_TYPES)]
    aname = get_default_agent_name(agent_id)
    agent = {
        "id": agent_id,
        "name": aname,
        "type": atype,
        "status": "idle",
        "current_task": None,
        "resume_pending_task": False,
        "progress": 0,
        "progress_message": "",
        "last_run": None,
        "last_result": None,
        "output_log": [],
        "stats": {},
        "git_repo_url": None,
        "git_token": None,
    }
    if agent_id == GIT_MANAGER_AGENT_ID:
        agent["name"] = "Git Manager"
        agent["progress"] = 100
        agent["progress_message"] = "Git manager idle"
        agent["output_log"].append({
            "time": datetime.utcnow().isoformat(),
            "type": "info",
            "message": "Git manager initialized and waiting for merge events."
        })
    elif agent_id == MASTER_AGENT_ID:
        agent["name"] = "Master Agent"
        agent["progress"] = 100
        agent["progress_message"] = "Master agent idle"
        agent["output_log"].append({
            "time": datetime.utcnow().isoformat(),
            "type": "info",
            "message": "Master agent initialized and waiting for orchestration/status events."
        })
    return agent


def _pick_best_dev_agent(project_token: Optional[str]) -> str:
    """Pick the most recently active or appropriate dev agent."""
    state = _ensure_project_state(project_token)
    project_agents = state["agent_states"]
    
    # Exclude system agents
    dev_agent_ids = [aid for aid in project_agents.keys() if not _is_system_agent_id(aid) and aid != DEPLOY_AGENT_ID]
    if not dev_agent_ids:
        return "agent_01" # Fallback
        
    # Pick the one with the most recent last_run or just the first one
    active = sorted(dev_agent_ids, key=lambda aid: project_agents[aid].get("last_run") or "", reverse=True)
    return active[0]


def get_default_agents(project_token: Optional[str] = None) -> List[Dict[str, Any]]:
    return [
        _make_agent(GIT_MANAGER_AGENT_ID, 0),
        _make_agent(MASTER_AGENT_ID, 1),
    ]

def initialize_agents_from_records(records: List[Any], project_token: Optional[str] = None) -> None:
    """
    Replace in-memory agent states with DB-backed agent records.
    """
    state = _ensure_project_state(project_token)
    state["claimed_task_ids"].clear()
    state["task_progress_state"].clear()
    state["timer_log_state"].clear()
    state["completed_milestones_synced"].clear()
    state["completed_sprints_synced"].clear()
    state["project_status_synced"] = None
    state["repo_bootstrap"] = _new_repo_bootstrap_state()
    state["repo_bootstrap_event"] = _make_asyncio_event()
    state["note_payload_cache"].clear()
    state["persisted_assignment_restore"] = {}
    state["workspace_contract_probe"] = {}
    agent_states = state["agent_states"]
    agent_states.clear()
    for idx, rec in enumerate(records):
        agent_id = getattr(rec, "id", None) or (rec.get("id") if isinstance(rec, dict) else None)
        if not agent_id:
            continue
        name = getattr(rec, "name", None) or (rec.get("name") if isinstance(rec, dict) else None)
        atype = getattr(rec, "type", None) or (rec.get("type") if isinstance(rec, dict) else None)
        agent = _make_agent(agent_id, idx)
        agent["name"] = normalize_agent_name(agent_id, name)
        if atype:
            agent["type"] = atype
        agent["skills_content"] = getattr(rec, "skills_content", None) or (rec.get("skills_content") if isinstance(rec, dict) else None)
        agent["skills_summary"] = getattr(rec, "skills_summary", None) or (rec.get("skills_summary") if isinstance(rec, dict) else None)
        agent["skills_tags"] = getattr(rec, "skills_tags", None) or (rec.get("skills_tags") if isinstance(rec, dict) else None)
        agent["specialization"] = getattr(rec, "specialization", None) or (rec.get("specialization") if isinstance(rec, dict) else None)
        agent["face"] = getattr(rec, "face", None) or (rec.get("face") if isinstance(rec, dict) else None)
        agent_states[agent_id] = agent

def ensure_project_initialized(project_token: Optional[str], records: List[Any]) -> None:
    state = _ensure_project_state(project_token)
    if not state["agent_states"]:
        initialize_agents_from_records(records, project_token=project_token)
        return
    agent_states = state["agent_states"]
    for idx, rec in enumerate(records):
        agent_id = getattr(rec, "id", None) or (rec.get("id") if isinstance(rec, dict) else None)
        if not agent_id or agent_id in agent_states:
            continue
        name = getattr(rec, "name", None) or (rec.get("name") if isinstance(rec, dict) else None)
        atype = getattr(rec, "type", None) or (rec.get("type") if isinstance(rec, dict) else None)
        agent = _make_agent(agent_id, idx)
        agent["name"] = normalize_agent_name(agent_id, name)
        if atype:
            agent["type"] = atype
        agent["skills_content"] = getattr(rec, "skills_content", None) or (rec.get("skills_content") if isinstance(rec, dict) else None)
        agent["skills_summary"] = getattr(rec, "skills_summary", None) or (rec.get("skills_summary") if isinstance(rec, dict) else None)
        agent["skills_tags"] = getattr(rec, "skills_tags", None) or (rec.get("skills_tags") if isinstance(rec, dict) else None)
        agent["specialization"] = getattr(rec, "specialization", None) or (rec.get("specialization") if isinstance(rec, dict) else None)
        agent["face"] = getattr(rec, "face", None) or (rec.get("face") if isinstance(rec, dict) else None)
        agent_states[agent_id] = agent

def get_completed_tasks(project_token: Optional[str]) -> List[Dict[str, Any]]:
    return list(_ensure_project_state(project_token)["completed_tasks"])


def _task_status_is_done(status: Any) -> bool:
    return str(status or "").strip().lower() in {
        "completed",
        "done",
        "complete",
        "closed",
        "resolved",
    }


# ── Valid status transitions ───────────────────────────────────────────────────
# Key: current status (lowered) → set of allowed next statuses (lowered)
_VALID_STATUS_TRANSITIONS: Dict[str, set] = {
    "to do": {"on going", "in progress", "to do"},   # self is idempotent re-fetch
    "on going": {"completed", "done", "complete", "closed", "failed", "blocked", "on going"},
    "in progress": {"completed", "done", "complete", "closed", "failed", "blocked", "in progress"},
    "blocked": {"on going", "in progress", "to do", "blocked"},
    "failed": {"on going", "in progress", "to do", "failed"},
    "completed": {"completed", "reopened"},  # NEVER allow completed→anything except reopen
    "done": {"done", "reopened"},
    "complete": {"complete", "reopened"},
    "closed": {"closed", "reopened"},
}


def _validate_status_transition(
    current_status: Any, new_status: Any, task_id: str = "?", agent_id: str = "?"
) -> Optional[str]:
    """
    Check whether a status transition is valid.

    Returns None if the transition is allowed, or a warning string if it looks
    suspicious (e.g. trying to complete an already-completed task).

    This is a soft guard — it logs but does not block execution — because
    remote statuses can drift between calls.
    """
    cur = str(current_status or "").strip().lower()
    new = str(new_status or "").strip().lower()

    if not cur or not new:
        return None  # can't validate without both sides

    if cur == new:
        return None  # idempotent — fine

    allowed = _VALID_STATUS_TRANSITIONS.get(cur)
    if allowed is None:
        # Unknown current status — warn but allow
        return f"Unknown current status '{cur}' for transition to '{new}' (task {task_id})"

    if new not in allowed:
        return (
            f"SUSPICIOUS transition: '{cur}' → '{new}' is NOT in allowed set "
            f"{allowed} (task {task_id}, agent {agent_id})"
        )

    return None  # valid transition


def _active_owned_task_ids(project_token: Optional[str]) -> set[str]:
    state = _ensure_project_state(project_token)
    owned = set()
    for agent in state["agent_states"].values():
        if (
            (agent.get("status") or "").lower() != "running"
            and not bool(agent.get("resume_pending_task"))
        ):
            continue
        current_task = agent.get("current_task")
        if not isinstance(current_task, dict):
            continue
        tid = str(_normalize_task_id(current_task) or current_task.get("external_id") or current_task.get("id") or "").strip()
        if tid:
            owned.add(tid)
        for linked in (current_task.get("linked_tasks") or []):
            linked_id = str(linked or "").strip()
            if linked_id:
                owned.add(linked_id)
    return owned


def _find_active_task_owner(task_id: str, project_token: Optional[str]) -> str:
    normalized_task_id = str(task_id or "").strip()
    if not normalized_task_id:
        return ""
    state = _ensure_project_state(project_token)
    for agent_id, agent in state["agent_states"].items():
        if _is_system_agent_id(agent_id):
            continue
        if (
            (agent.get("status") or "").lower() != "running"
            and not bool(agent.get("resume_pending_task"))
        ):
            continue
        current_task = agent.get("current_task")
        if not isinstance(current_task, dict):
            continue
        current_task_id = _task_identity(current_task)
        if current_task_id and current_task_id == normalized_task_id:
            return agent_id
        for linked in (current_task.get("linked_tasks") or []):
            if str(linked or "").strip() == normalized_task_id:
                return agent_id
    return ""

